function pulse(){manualPulse=1;dirty=true;}
function tap(){const now=performance.now()/1000;tapTimes.push(now);tapTimes=tapTimes.slice(-8);const r=tempoEstimate(tapTimes);tapBpm=r.bpm;refreshDeck(true);}
